contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    function run(address callerAddr, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt && address(this).balance >= collectAmt);

        // read before values
        uint beforeBalMapping = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Deposit by sending Ether using Deposit()
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read after deposit values
        uint afterBalMapping = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // Now attempt Collect: call Collect with collectAmt
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after collect values
        uint finalBalMapping = c.balances(address(this));
        uint finalContractBal = address(c).balance;

        // General rule asserted:
        // 1) If Deposit did not revert then mapping increased exactly by depositAmt and contract balance increased by depositAmt
        // 2) If Deposit reverted then no change in mapping and contract balance
        // 3) If Collect did not revert then mapping decreased by collectAmt and contract balance decreased by collectAmt
        // 4) If Collect reverted then mapping and contract balance unchanged by the Collect call
        assert(
            (
                (!depositReverted && afterBalMapping == beforeBalMapping + depositAmt && afterContractBal == beforeContractBal + depositAmt)
                || (depositReverted && afterBalMapping == beforeBalMapping && afterContractBal == beforeContractBal)
            )
            &&
            (
                (!collectReverted && finalBalMapping + collectAmt == afterBalMapping && finalContractBal + collectAmt == afterContractBal)
                || (collectReverted && finalBalMapping == afterBalMapping && finalContractBal == afterContractBal)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Test attempts a Deposit (possibly 0) and then a Collect; ensures Collect's effects on balances are consistent
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt);

        // Observe mapping and contract balance before Deposit
        uint beforeMap = c.balances(address(this));
        uint beforeCtrBal = address(c).balance;

        // Perform Deposit (may revert) by sending Ether to c.Deposit
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Observe after-Deposit state
        uint afterDepositMap = c.balances(address(this));
        uint afterDepositCtrBal = address(c).balance;

        // Now attempt Collect
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe final state after Collect
        uint finalMap = c.balances(address(this));
        uint finalCtrBal = address(c).balance;

        // General rule:
        // - The Deposit call, if it succeeded, increases the mapping and contract balance by depositAmt; if it reverted, no change.
        // - The Collect call, if it succeeded, decreases both the mapping and contract balance by exactly collectAmt; if it reverted, no change.
        // We express this as a conjunction of the two behaviors using only observable values and revert flags.
        assert(
            (
                (!depositReverted && afterDepositMap == beforeMap + depositAmt && afterDepositCtrBal == beforeCtrBal + depositAmt)
                || (depositReverted && afterDepositMap == beforeMap && afterDepositCtrBal == beforeCtrBal)
            )
            &&
            (
                (!collectReverted && finalMap + collectAmt == afterDepositMap && finalCtrBal + collectAmt == afterDepositCtrBal)
                || (collectReverted && finalMap == afterDepositMap && finalCtrBal == afterDepositCtrBal)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to optionally deposit first and then attempt Collect.
    // depositAmt is sent to Deposit; collectAmt is used in Collect call.
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt);

        // Make an initial deposit (may revert). Use try/catch to observe.
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Read observable state before Collect
        uint beforeBalanceMap = c.balances(address(this));
        uint minSum = c.MinSum();

        // Attempt Collect and observe whether it reverts
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // If Collect succeeded (did not revert) then caller's mapping before the Collect must have been >= MinSum and >= collectAmt.
        // We express this as: !collectReverted => (beforeBalanceMap >= minSum && beforeBalanceMap >= collectAmt)
        assert(collectReverted || (beforeBalanceMap >= minSum && beforeBalanceMap >= collectAmt));
    }

    receive() external payable { }
}
